func parsePortedParserSourceCase(language, method, input string) *Node {
	newParser := NewParser
	switch language {
	case "less":
		newParser = NewLESSParser
	case "scss":
		newParser = NewSCSSParser
	}
	p := newParser()
	sourceLen := len([]rune(input))
	switch method {
	case "parseStylesheet":
		return p.ParseStylesheet(input)
	case "parseRuleset":
		return p.InternalParse(input, p.parseRuleset)
	case "parseVariable":
		return p.InternalParse(input, p.parseVariable)
	case "parseVariableDeclaration":
		return p.InternalParse(input, func() *Node { return p.parseVariableDeclaration(0, sourceLen) })
	case "parseDeclaration", "parseRuleSetDeclaration", "parseProperty":
		return p.InternalParse(input, func() *Node { return p.parseDeclaration(0, sourceLen) })
	case "tryParseMixinDeclaration", "parseMixinDeclaration":
		return p.InternalParse(input, p.parseLESSMixinDeclaration)
	case "tryParseMixinReference":
		return p.InternalParse(input, p.parseLESSMixinReference)
	case "parseMixinParameter":
		return p.InternalParse(input, p.parseLESSMixinParameter)
	case "parseExpr":
		return p.InternalParse(input, p.parseExpression)
	case "parseTerm", "parseFunction", "parseHexColor":
		return p.InternalParse(input, p.parseTerm)
	case "parsePrio":
		return p.InternalParse(input, p.parsePrio)
	case "parseOperator", "parseUnaryOperator":
		return p.InternalParse(input, p.parseOperator)
	case "parseURILiteral":
		return p.InternalParse(input, p.parseURILiteral)
	case "parseInterpolation":
		return nil
	case "parseFontFace":
		return p.InternalParse(input, p.parseFontFace)
	case "parseKeyframe":
		return p.InternalParse(input, p.parseKeyframe)
	case "parseSelector", "parseSimpleSelector", "parseElementName", "parseAttrib", "parsePseudo", "parseClass", "parseCombinator", "parseMedium", "parseMediaQueryList":
		return p.InternalParse(input, func() *Node { return p.parseSelector(0, sourceLen) })
	case "parseModuleMember":
		return p.InternalParse(input, func() *Node {
			node, _, ok := p.parseModuleMemberTerm(0, sourceLen)
			if !ok {
				return nil
			}
			return node
		})
	default:
		return p.ParseStylesheet(input)
	}
}

func shortParserCaseName(input string) string {
	if len(input) <= 48 {
		return input
	}
	return input[:48]
}
